class Solution { public: int maxDistance(vector<vector<int>>& grid){int rows=grid.size(),columns=grid[0].size();queue<pair<int,int>> pending;for(int r=0;r<rows;++r)for(int c=0;c<columns;++c)if(grid[r][c])pending.push({r,c});if(pending.empty()||(int)pending.size()==rows*columns)return -1;int distance=-1,directions[5]={1,0,-1,0,1};while(!pending.empty()){int size=pending.size();++distance;while(size--){auto [row,column]=pending.front();pending.pop();for(int d=0;d<4;++d){int r=row+directions[d],c=column+directions[d+1];if(r>=0&&r<rows&&c>=0&&c<columns&&!grid[r][c]){grid[r][c]=1;pending.push({r,c});}}}}return distance;} };
